using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using System.IO;
public class Base64Image : MonoBehaviour
{
    
    
    
    private string base64 = "";
    private void Start()
    {
        
       
        Save();
    }
    public void Save()
    {
        try
        {
            // 将Base64字符串转换为字节数组
            byte[] bytes = Convert.FromBase64String(base64);

            // 创建一个新的Texture2D对象并将字节数组加载到其中
            Texture2D texture = new Texture2D(2, 2);
            texture.LoadImage(bytes);

            // 将纹理编码为PNG格式的字节数组
            byte[] pngBytes = texture.EncodeToJPG();
            
            
            // 指定文件名并将文件保存到Application.persistentDataPath目录下
            string filename = "myImage.jgp";
            string path = Path.Combine(Application.persistentDataPath, filename);
            File.WriteAllBytes(path, pngBytes);

             Log.Debug("保存图片到" + path);
        }
        catch (Exception e)
        {
             Log.Debug("保存图片失败: " + e.Message);
        }
    }
    
    
    
